/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountBentoFeatures, type BentoFeaturesOptions } from "../../components/bento-features/BentoFeaturesEngine.js";
import type { MotionController } from "../../components/bento-features/motion-runtime";

export function BentoFeatures({ options, className }: { options?: BentoFeaturesOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountBentoFeatures(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="bento-features" />;
}

